16	
17	    /** Maximum number of owners permitted per city. */
18	    static final int CAPACITY = 50;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws CityAtCapacityException {
22	        String city = request.getCity();
23	        long count = ownerRepository.findAll().stream()
24	                .filter(o -> city == null ? o.getCity() == null : city.equals(o.getCity()))
25	                .count();
26	        if (count >= CAPACITY) {
27	            throw new CityAtCapacityException(city, CAPACITY);
28	        }
29	    }
30	}
